import { authHeader } from './actions.mjs';
import { assertHarnessSpecifier, assertRelativePath } from './safety.mjs';

const METHODS = new Map([['GET', 'get'], ['POST', 'post'], ['PUT', 'put'], ['PATCH', 'patch'], ['DELETE', 'delete']]);

export function generateSpec(scenarioDoc, { harnessSpecifier }) {
  assertHarnessSpecifier(harnessSpecifier);
  if (scenarioDoc?.auth?.scheme !== 'Bearer') throw new Error('Generated tests only support the baseline Bearer scheme');
  const lines = [
    '// Generated by code-first-service-tests. Do not edit.',
    '// SYNTHETIC fixture. Assertions come from baseline/behavior-baseline.json.',
    '// This file is not an oracle of the service implementation.',
    "import { test, expect, request as playwrightRequest } from '@playwright/test';",
    `import { startServer, resetStore } from '${harnessSpecifier}';`,
    '',
    'let server;',
    'let api;',
    '',
    'test.beforeAll(async () => {',
    '  server = await startServer();',
    '  if (!/^http:\\/\\/127\\.0\\.0\\.1:\\d+$/.test(server.baseURL)) {',
    "    throw new Error('Refusing non-loopback base URL');",
    '  }',
    '  api = await playwrightRequest.newContext({ baseURL: server.baseURL });',
    '});',
    '',
    'test.afterEach(() => {',
    '  resetStore();',
    '});',
    '',
    'test.afterAll(async () => {',
    '  await api.dispose();',
    '  await server.close();',
    '});',
    '',
  ];
  for (const scenario of scenarioDoc.scenarios) {
    if (!scenario.executable) continue;
    if (scenario.classification !== 'approved_requirement' && scenario.classification !== 'accepted_regression_behavior') continue;
    lines.push(`// BEGIN ${scenario.id}`);
    lines.push(...renderScenario(scenario, scenarioDoc.auth));
    lines.push(`// END ${scenario.id}`, '');
  }
  return lines.join('\n');
}

export function specBlock(spec, id) {
  const begin = `// BEGIN ${id}\n`;
  const end = `// END ${id}\n`;
  const start = spec.indexOf(begin);
  const stop = spec.indexOf(end);
  if (start < 0 || stop < 0) throw new Error(`Missing generated block ${id}`);
  return spec.slice(start, stop + end.length);
}

function renderScenario(scenario, auth) {
  const lines = [
    `test(${JSON.stringify(scenario.id)}, async () => {`,
    `  test.info().annotations.push({ type: 'classification', description: ${JSON.stringify(scenario.classification)} });`,
    `  test.info().annotations.push({ type: 'intent', description: ${JSON.stringify(scenario.intent)} });`,
    `  test.info().annotations.push({ type: 'evidence', description: ${JSON.stringify(evidenceText(scenario))} });`,
    '  const vars = {};',
  ];
  for (const action of scenario.actions) {
    const method = METHODS.get(action.method);
    if (!method) throw new Error(`Unsupported method ${action.method}`);
    assertRelativePath(action.path);
    const options = { failOnStatusCode: false };
    const headers = authHeader(action.auth, auth);
    if (headers) options.headers = headers;
    if (action.body !== undefined) options.data = action.body;
    lines.push('  {');
    lines.push(`    const response = await api.${method}(${emitPath(action.path)}, ${JSON.stringify(options)});`);
    lines.push('    const responseBody = await response.json();');
    for (const assertion of scenario.assertions.filter((item) => item.action === action.id)) {
      lines.push(...renderAssertion(scenario.id, assertion));
    }
    for (const extraction of scenario.extractions.filter((item) => item.action === action.id)) {
      if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(extraction.name)) throw new Error('Unsafe extraction name');
      lines.push(`    vars.${extraction.name} = ${emitBodyPath(extraction.path)};`);
    }
    lines.push('  }');
  }
  lines.push('});');
  return lines;
}

function renderAssertion(id, assertion) {
  const keys = Object.keys(assertion).filter((key) => key !== 'action');
  if (keys.length !== 1) throw new Error(`Assertion for ${id} must have one check`);
  const [kind] = keys;
  if (kind === 'status') {
    return [`    expect(response.status(), ${JSON.stringify(`${id} status`)}).toBe(${JSON.stringify(assertion.status)});`];
  }
  if (kind === 'bodyEquals') {
    return [`    expect(responseBody, ${JSON.stringify(`${id} bodyEquals`)}).toEqual(${JSON.stringify(assertion.bodyEquals)});`];
  }
  if (kind === 'bodyMatch') {
    return [`    expect(responseBody, ${JSON.stringify(`${id} bodyMatch`)}).toMatchObject(${JSON.stringify(assertion.bodyMatch)});`];
  }
  if (kind === 'bodyField') {
    const { path, type, equalsExtraction } = assertion.bodyField;
    const value = emitBodyPath(path);
    if (type === 'non_empty_string') {
      return [
        `    expect(typeof ${value}, ${JSON.stringify(`${id} ${path} type`)}).toBe('string');`,
        `    expect(${value}.length, ${JSON.stringify(`${id} ${path} length`)}).toBeGreaterThan(0);`,
      ];
    }
    if (typeof equalsExtraction === 'string') {
      if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(equalsExtraction)) throw new Error('Unsafe extraction reference');
      return [`    expect(${value}, ${JSON.stringify(`${id} ${path}`)}).toBe(vars.${equalsExtraction});`];
    }
  }
  throw new Error(`Unsupported assertion ${kind}`);
}

function emitBodyPath(path) {
  if (typeof path !== 'string' || !/^[A-Za-z_][A-Za-z0-9_]*$/.test(path)) throw new Error(`Unsafe body path ${path}`);
  return `responseBody.${path}`;
}

function emitPath(path) {
  if (!path.includes('{{')) return JSON.stringify(path);
  const parts = [];
  const pattern = /\{\{([A-Za-z_][A-Za-z0-9_]*)\}\}/g;
  let last = 0;
  for (const match of path.matchAll(pattern)) {
    if (match.index > last) parts.push(JSON.stringify(path.slice(last, match.index)));
    parts.push(`encodeURIComponent(String(vars.${match[1]}))`);
    last = match.index + match[0].length;
  }
  if (last < path.length) parts.push(JSON.stringify(path.slice(last)));
  if (path.slice(last).includes('{')) throw new Error(`Unresolved path ${path}`);
  return parts.join(' + ');
}

function evidenceText(scenario) {
  return scenario.evidence.map((entry) => `${entry.role} ${entry.file}:${entry.line} ${entry.symbol}`).join('; ');
}
